INSERT INTO `userActivity` (userId, loginCount, lastLogin) SELECT 'QQrveSvG10G2', `loginCount`, `lastLogin` FROM `userActivity` WHERE userId = 'dTygqS3HWCYsssnVaOzZ9VX5hdK7lGVb'
