ON CONFLICT (userId, featureId) DO UPDATE SET `isVisited` = max(userFeature.isVisited, excluded.isVisited), `isWishlisted` = max(userFeature.isWishlisted, excluded.isWishlisted), `visitedAt` = coalesce(userFeature.visitedAt, excluded.visitedAt), `createdAt` = min(userFeature.createdAt, excluded.createdAt), `modifiedAt` = max(userFeature.modifiedAt, excluded.modifiedAt);
